37	
38	template <typename aType, typename bType, typename accType, typename outType>
39	class MatmulLeakyKernel {
40	public:
41	    __aicore__ inline MatmulLeakyKernel() {}
42	    __aicore__ inline void Init(GM_ADDR a, GM_ADDR b, GM_ADDR c, GM_ADDR workspace,
43	                                GM_ADDR tiling, AscendC::TPipe *pipe);
44	    __aicore__ inline void Process();
45	
46	    MatmulKernel<aType, bType, accType> mm_;
47	    AscendC::GlobalTensor<aType> aGM_;
48	    AscendC::GlobalTensor<bType> bGM_;
49	    AscendC::GlobalTensor<outType> cGM_;
50	    WorkspaceQueue<accType, WORKSPACE_DEPTH> wsQueue_;
51	    MatmulLeakyReluTiling tiling;
52	    LeakyKernel<accType, outType> leakyKernel_;
53	    BlockScheduler sched_;
54	    int subTileM_;
55	};
56	
57	/**
58	  * @brief  Set matmulLeaky input and output gm addr of current core.
59	  * @param  a: A matrix gm addr.
60	  * @param  b: B matrix gm addr.
61	  * @param  c: C matrix gm addr.
62	  * @param  workspace: Temporary gm space addr required by matmul calc.
63	  * @param  tiling: matmul tiling data.
64	  * @param  pipe: Global memory and sync management TPipe object.
65	  * @retval None
66	  */
67	template <typename aType, typename bType, typename accType, typename outType>
68	__aicore__ inline void MatmulLeakyKernel<aType, bType, accType, outType>::Init(GM_ADDR a, GM_ADDR b,
69	                                                                    GM_ADDR c, GM_ADDR workspace,
70	                                                                    GM_ADDR tilingGM, AscendC::TPipe *pipe)
71	{
72	    CopyTiling(&this->tiling, tilingGM);
73	
74	    aGM_.SetGlobalBuffer(reinterpret_cast<__gm__ aType *>(a), tiling.M * tiling.K);
75	    bGM_.SetGlobalBuffer(reinterpret_cast<__gm__ bType *>(b), tiling.K * tiling.N);
76	    cGM_.SetGlobalBuffer(reinterpret_cast<__gm__ outType *>(c), tiling.M * tiling.N);
77	
78	    int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
79	    sched_.Init(tiling.M, tiling.N, tiling.baseM, tiling.baseN,
80	                AscendC::GetBlockNum(), coreIdx);
81	
82	    // Setup workspace ring buffer for cube->vector data transfer
83	    uint32_t wsOffset = coreIdx * WORKSPACE_DEPTH * tiling.baseM * tiling.baseN;
84	    wsQueue_.Init(workspace + wsOffset * sizeof(accType),
85	                  tiling.baseM * tiling.baseN,
86	                  CUBE_NOTIFY_VECTOR_ID, VECTOR_NOTIFY_CUBE_ID);
87	
88	    if ASCEND_IS_AIC {
89	        mm_.Init(tiling.K, tiling.K, tiling.N,
90	                 tiling.baseM, tiling.baseN, tiling.baseK, tiling.l1Prefetch,
91	                 *pipe);
92	    }
93	
94	    if ASCEND_IS_AIV {
95	        subTileM_ = tiling.baseM / AscendC::GetSubBlockNum();
96	        leakyKernel_.Init(subTileM_, tiling.baseN, pipe);
97	        wsQueue_.InitFreeSlots();
98	    }
99	}
100	
101	/**
102	  * @brief  Main process of matmul calculation
103	  * @retval None
104	  */
105	template <typename aType, typename bType, typename accType, typename outType>
106	__aicore__ inline void MatmulLeakyKernel<aType, bType, accType, outType>::Process()
107	{
108	    int mIdx, nIdx;
109	    while (sched_.HasNext()) {
110	        sched_.Next(mIdx, nIdx);
111	        if ASCEND_IS_AIC {
112	            auto slot = wsQueue_.ProducerAcquire();
113	            auto aBlock = aGM_[mIdx * tiling.baseM * tiling.K];
114	            auto bBlock = bGM_[nIdx * tiling.baseN];
115	            mm_.ComputeBlock(aBlock, bBlock, slot);
116	            wsQueue_.ProducerRelease();
117	        }
118	        if ASCEND_IS_AIV {
119	            auto slot = wsQueue_.ConsumerAcquire();
120	            int rowOffset = AscendC::GetSubBlockIdx() * subTileM_;
121	            auto subSlot = slot[rowOffset * tiling.baseN];
122	            auto cBlock = cGM_[(mIdx * tiling.baseM + rowOffset) * tiling.N + nIdx * tiling.baseN];
123	            leakyKernel_.Process(subSlot, cBlock, tiling.N);
124	            wsQueue_.ConsumerRelease();
125	        }
126	    }
127	}
