16	// CRTP base for MatmulKernel templates shared between quant_matmul and matmul_leakyrelu.
17	// Derived must provide accessors: base_m(), base_n(), base_k(), base_mk(), base_kn(), base_mn(),
18	// l1_prefetch().
19	template <typename Derived, typename aType, typename bType, typename cType>
20	class MatmulKernelBase {
21	    static_assert(std::is_same<aType, bType>::value, "aType and bType must be the same type");
22	    static constexpr uint32_t C0 = 32 / sizeof(aType);
23	
24	public:
25	    __aicore__ inline MatmulKernelBase() {}
26	    __aicore__ inline void ComputeBlock(const AscendC::GlobalTensor<aType> &aBlock,
27	                                        const AscendC::GlobalTensor<bType> &bBlock,
28	                                        const AscendC::GlobalTensor<cType> &cBlock);
29	
30	protected:
31	    AscendC::TQue<AscendC::TPosition::A1, 1> inQueueA1;
32	    AscendC::TQue<AscendC::TPosition::A2, 1> inQueueA2;
33	    AscendC::TQue<AscendC::TPosition::B1, 1> inQueueB1;
34	    AscendC::TQue<AscendC::TPosition::B2, 1> inQueueB2;
35	    AscendC::TQue<AscendC::TPosition::CO1, 1> outQueueCO1;
36	
37	    uint32_t k_;
38	    uint32_t a_dvalue_, b_dvalue_;
39	
40	    __aicore__ inline void CopyA(const AscendC::GlobalTensor<aType> &A, uint32_t kLen);
41	    __aicore__ inline void CopyB(const AscendC::GlobalTensor<bType> &B, uint32_t kLen);
42	    __aicore__ inline void SplitA(const AscendC::LocalTensor<aType> &a1Local,
43	                                  uint32_t offset, uint32_t colC0Stride);
44	    __aicore__ inline void SplitB(const AscendC::LocalTensor<bType> &b1Local,
45	                                  uint32_t offset, uint32_t colC0Stride);
46	    __aicore__ inline void Compute(const AscendC::LocalTensor<cType> &c1Local, bool cmatrixInitVal);
47	    __aicore__ inline void CopyOut(const AscendC::GlobalTensor<cType> &C);
48	
49	private:
50	    __aicore__ inline Derived &self() { return static_cast<Derived &>(*this); }
51	    __aicore__ inline const Derived &self() const { return static_cast<const Derived &>(*this); }
52	};
53	
54	// ---------------------------------------------------------------------------
55	// ComputeBlock
56	// ---------------------------------------------------------------------------
57	template <typename Derived, typename aType, typename bType, typename cType>
58	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::ComputeBlock(
59	    const AscendC::GlobalTensor<aType> &aBlock,
60	    const AscendC::GlobalTensor<bType> &bBlock,
61	    const AscendC::GlobalTensor<cType> &cBlock)
62	{
63	    AscendC::LocalTensor<cType> c1Local = outQueueCO1.AllocTensor<cType>();
64	    uint32_t kTiles = k_ / self().base_k();
65	
66	    for (uint32_t outer = 0; outer < kTiles; outer += self().l1_prefetch()) {
67	        uint32_t count = (kTiles - outer < self().l1_prefetch())
68	                             ? (kTiles - outer) : self().l1_prefetch();
69	        uint32_t kLen = count * self().base_k();
70	
71	        CopyA(aBlock[outer * self().base_k()], kLen);
72	        CopyB(bBlock[outer * self().base_k() * b_dvalue_], kLen);
73	
74	        AscendC::LocalTensor<aType> a1Local = inQueueA1.DeQue<aType>();
75	        AscendC::LocalTensor<bType> b1Local = inQueueB1.DeQue<bType>();
76	
77	        for (uint32_t i = 0; i < count; i++) {
78	            SplitA(a1Local, i * self().base_mk(), self().base_m());
79	            SplitB(b1Local, i * self().base_k() * C0, kLen);
80	            Compute(c1Local, (outer + i == 0));
81	        }
82	
83	        inQueueA1.FreeTensor(a1Local);
84	        inQueueB1.FreeTensor(b1Local);
85	    }
86	
87	    outQueueCO1.EnQue(c1Local);
88	    CopyOut(cBlock);
89	}
90	
91	// ---------------------------------------------------------------------------
92	// CopyA
93	// ---------------------------------------------------------------------------
94	template <typename Derived, typename aType, typename bType, typename cType>
95	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::CopyA(
96	    const AscendC::GlobalTensor<aType> &A, uint32_t kLen)
97	{
98	    auto a1Local = inQueueA1.AllocTensor<aType>();
99	    LoadNdGmToNzL1(a1Local, A, self().base_m(), kLen, a_dvalue_);
100	    inQueueA1.EnQue(a1Local);
101	}
102	
103	// ---------------------------------------------------------------------------
104	// CopyB
105	// ---------------------------------------------------------------------------
106	template <typename Derived, typename aType, typename bType, typename cType>
107	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::CopyB(
108	    const AscendC::GlobalTensor<bType> &B, uint32_t kLen)
109	{
110	    AscendC::LocalTensor<bType> b1Local = inQueueB1.AllocTensor<bType>();
111	    LoadNdGmToNzL1(b1Local, B, kLen, self().base_n(), b_dvalue_);
112	    inQueueB1.EnQue(b1Local);
113	}
114	
115	// ---------------------------------------------------------------------------
116	// SplitA
117	// ---------------------------------------------------------------------------
118	template <typename Derived, typename aType, typename bType, typename cType>
119	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::SplitA(
120	    const AscendC::LocalTensor<aType> &a1Local, uint32_t offset, uint32_t colC0Stride)
121	{
122	    AscendC::LocalTensor<aType> a2Local = inQueueA2.AllocTensor<aType>();
123	    LoadNzL1ToZzL0A(a2Local, a1Local[offset], self().base_m(), self().base_k(), colC0Stride);
124	    inQueueA2.EnQue(a2Local);
125	}
126	
127	// ---------------------------------------------------------------------------
128	// SplitB
129	// ---------------------------------------------------------------------------
130	template <typename Derived, typename aType, typename bType, typename cType>
131	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::SplitB(
132	    const AscendC::LocalTensor<bType> &b1Local, uint32_t offset, uint32_t colC0Stride)
133	{
134	    AscendC::LocalTensor<bType> b2Local = inQueueB2.AllocTensor<bType>();
135	    LoadNzL1ToZnL0B(b2Local, b1Local[offset], self().base_k(), self().base_n(), colC0Stride);
136	    inQueueB2.EnQue(b2Local);
137	}
138	
139	// ---------------------------------------------------------------------------
140	// Compute
141	// ---------------------------------------------------------------------------
142	template <typename Derived, typename aType, typename bType, typename cType>
143	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::Compute(
144	    const AscendC::LocalTensor<cType> &c1Local, bool cmatrixInitVal)
145	{
146	    AscendC::LocalTensor<aType> a2Local = inQueueA2.DeQue<aType>();
147	    AscendC::LocalTensor<bType> b2Local = inQueueB2.DeQue<bType>();
148	    AscendC::MmadParams mmadParams;
149	    mmadParams.m = self().base_m();
150	    mmadParams.n = self().base_n();
151	    mmadParams.k = self().base_k();
152	    mmadParams.cmatrixInitVal = cmatrixInitVal;
153	    AscendC::Mmad(c1Local, a2Local, b2Local, mmadParams);
154	    inQueueA2.FreeTensor(a2Local);
155	    inQueueB2.FreeTensor(b2Local);
156	}
157	
158	// ---------------------------------------------------------------------------
159	// CopyOut
160	// ---------------------------------------------------------------------------
161	template <typename Derived, typename aType, typename bType, typename cType>
162	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::CopyOut(
163	    const AscendC::GlobalTensor<cType> &C)
164	{
165	    auto c1Local = outQueueCO1.DeQue<cType>();
166	    FixpipeNzL0cToNdGm(C, c1Local, self().base_m(), self().base_n());
167	    outQueueCO1.FreeTensor(c1Local);
168	}
