19	static inline int64_t GetWorkspaceSize(const MatmulLeakyReluTiling *tiling, int accElementSize,
20	                                       uint32_t usedCoreNum)
21	{
22	    return tiling->baseM * tiling->baseN * WORKSPACE_DEPTH * accElementSize * usedCoreNum;
23	}
24	
25	at::Tensor matmul_leakyrelu(const at::Tensor &a, const at::Tensor &b)
26	{
27	    TORCH_CHECK(a.dim() == 2, "matmul_leakyrelu a must be two-dimensional.");
28	    TORCH_CHECK(b.dim() == 2, "matmul_leakyrelu b must be two-dimensional.");
29	    TORCH_CHECK(a.sizes()[1] == b.sizes()[0], "matmul_leakyrelu k must be same.");
30	    TORCH_CHECK(a.scalar_type() == b.scalar_type(), "matmul_leakyrelu a and b must have same dtype.");
31	
32	    uint32_t usedCoreNum = 20;
33	    uint32_t m = static_cast<uint32_t>(a.sizes()[0]);
34	    uint32_t n = static_cast<uint32_t>(b.sizes()[1]);
35	    uint32_t k = static_cast<uint32_t>(a.sizes()[1]);
36	
37	    at::Tensor c = at::empty({static_cast<int64_t>(m), static_cast<int64_t>(n)},
38	                             at::device(at::kPrivateUse1).dtype(at::kFloat));
39	
40	    at::Tensor t = at::empty({static_cast<int64_t>(sizeof(MatmulLeakyReluTiling))},
41	                             at::device(at::kCPU).dtype(at::kByte));
42	    auto *tiling_ptr = reinterpret_cast<MatmulLeakyReluTiling *>(t.data_ptr());
43	    tiling_ptr->M = static_cast<int32_t>(m);
44	    tiling_ptr->N = static_cast<int32_t>(n);
45	    tiling_ptr->K = static_cast<int32_t>(k);
46	    tiling_ptr->baseM = DEFAULT_BASE_M;
47	    tiling_ptr->baseN = DEFAULT_BASE_N;
48	    tiling_ptr->baseK = DEFAULT_BASE_K;
49	    tiling_ptr->l1Prefetch = DEFAULT_L1_PREFETCH;
50	    auto tiling_npu = t.to(at::kPrivateUse1);
51	
52	    uint32_t blockDim = usedCoreNum;
53	
54	    if (a.scalar_type() == at::kHalf) {
55	        int accElementSize = sizeof(float);
56	        int64_t workSpaceSize = GetWorkspaceSize(tiling_ptr, accElementSize, usedCoreNum);
57	        at::Tensor w = at::empty({workSpaceSize}, at::device(at::kPrivateUse1).dtype(at::kByte));
58	        EXEC_KERNEL_CMD(matmul_leakyrelu_fp16, blockDim, a, b, c, w, tiling_npu);
59	    } else if (a.scalar_type() == at::kChar) {
60	        int accElementSize = sizeof(int32_t);
61	        int64_t workSpaceSize = GetWorkspaceSize(tiling_ptr, accElementSize, usedCoreNum);
62	        at::Tensor w = at::empty({workSpaceSize}, at::device(at::kPrivateUse1).dtype(at::kByte));
63	        EXEC_KERNEL_CMD(matmul_leakyrelu_int8, blockDim, a, b, c, w, tiling_npu);
64	    } else {
65	        TORCH_CHECK(false, "matmul_leakyrelu unsupported dtype, expected float16 or int8.");
66	    }
67	
68	    return c;
69	}
