/**
 * @file hyena_fft_size_padding_rfft.cpp
 * @brief AscendC kernel for Hyena FFT via direct DFT-GEMM.
 *
 * Computes two GEMMs on the Cube unit:
 *   OutRe = X @ CosW_T   (Real part)
 *   OutIm = X @ SinW_T   (Imaginary part)
 *
 * All dimensions are padded to multiples of baseM/baseK/baseN by the host.
 * Each (M,N) block produces one output tile for both real and imag parts.
 */

#include "kernel_operator.h"
#include "matmul_tile.h"
#include "kernel_common.h"
#include "hyena_fft_tiling.h"

using namespace AscendC;

// ============================================================================
// MatmulCompute: Encapsulates one GEMM (GM→L1→L0→Mmad→L0C→GM)
// ============================================================================
template <typename T>
class MatmulCompute {
    static constexpr uint32_t C0 = 32 / sizeof(T);

public:
    __aicore__ inline MatmulCompute() {}

    __aicore__ inline void Init(uint32_t k, uint32_t lda, uint32_t ldb,
                                uint32_t baseM, uint32_t baseN, uint32_t baseK,
                                uint32_t l1Prefetch, TPipe &pipe)
    {
        baseM_ = baseM;
        baseN_ = baseN;
        baseK_ = baseK;
        l1Prefetch_ = l1Prefetch;
        baseMK_ = baseM_ * baseK_;
        baseKN_ = baseK_ * baseN_;
        baseMN_ = baseM_ * baseN_;
        k_ = k;
        aDvalue_ = lda;
        bDvalue_ = ldb;

        pipe.InitBuffer(inQueueA1_, 2, baseMK_ * l1Prefetch_ * sizeof(T));
        pipe.InitBuffer(inQueueA2_, 2, baseMK_ * sizeof(T));
        pipe.InitBuffer(inQueueB1_, 2, baseKN_ * l1Prefetch_ * sizeof(T));
        pipe.InitBuffer(inQueueB2_, 2, baseKN_ * sizeof(T));
        pipe.InitBuffer(outQueueCO1_, 1, baseMN_ * sizeof(float));
    }

    __aicore__ inline void ComputeBlock(
        const GlobalTensor<T> &aBlock, const GlobalTensor<T> &bBlock,
        GlobalTensor<float> &cBlock)
    {
        LocalTensor<float> c1Local = outQueueCO1_.AllocTensor<float>();
        uint32_t kTiles = k_ / baseK_;

        for (uint32_t outer = 0; outer < kTiles; outer += l1Prefetch_) {
            uint32_t count = (kTiles - outer < l1Prefetch_)
                                 ? (kTiles - outer) : l1Prefetch_;
            uint32_t kLen = count * baseK_;

            // CopyA: load X tile GM → L1
            {
                auto a1Local = inQueueA1_.AllocTensor<T>();
                LoadNdGmToNzL1(a1Local,
                               aBlock[outer * baseK_], baseM_, kLen, aDvalue_);
                inQueueA1_.EnQue(a1Local);
            }

            // CopyB: load weight tile GM → L1
            {
                auto b1Local = inQueueB1_.AllocTensor<T>();
                LoadNdGmToNzL1(b1Local,
                               bBlock[outer * baseK_ * bDvalue_],
                               baseK_ * count, baseN_, bDvalue_);
                inQueueB1_.EnQue(b1Local);
            }

            LocalTensor<T> a1Local = inQueueA1_.DeQue<T>();
            LocalTensor<T> b1Local = inQueueB1_.DeQue<T>();

            for (uint32_t i = 0; i < count; i++) {
                // SplitA: L1 → L0A
                {
                    auto a2Local = inQueueA2_.AllocTensor<T>();
                    LoadNzL1ToZzL0A(a2Local,
                                    a1Local[i * baseMK_], baseM_, baseK_, baseM_);
                    inQueueA2_.EnQue(a2Local);
                }

                // SplitB: L1 → L0B
                {
                    auto b2Local = inQueueB2_.AllocTensor<T>();
                    LoadNzL1ToZnL0B(b2Local,
                                    b1Local[i * baseKN_], baseK_, baseN_, C0 * baseK_);
                    inQueueB2_.EnQue(b2Local);
                }

                // Compute: Mmad
                {
                    LocalTensor<T> a2Local = inQueueA2_.DeQue<T>();
                    LocalTensor<T> b2Local = inQueueB2_.DeQue<T>();
                    MmadParams mmadParams;
                    mmadParams.m = baseM_;
                    mmadParams.n = baseN_;
                    mmadParams.k = baseK_;
                    mmadParams.cmatrixInitVal = (outer + i == 0);
                    Mmad(c1Local, a2Local, b2Local, mmadParams);
                    inQueueA2_.FreeTensor(a2Local);
                    inQueueB2_.FreeTensor(b2Local);
                }
            }

            inQueueA1_.FreeTensor(a1Local);
            inQueueB1_.FreeTensor(b1Local);
        }

        // CopyOut: L0C → GM
        outQueueCO1_.EnQue(c1Local);
        {
            auto c1LocalOut = outQueueCO1_.DeQue<float>();
            FixpipeNzL0cToNdGm(cBlock, c1LocalOut, baseM_, baseN_);
            outQueueCO1_.FreeTensor(c1LocalOut);
        }
    }

private:
    TQue<TPosition::A1, 1> inQueueA1_;
    TQue<TPosition::A2, 1> inQueueA2_;
    TQue<TPosition::B1, 1> inQueueB1_;
    TQue<TPosition::B2, 1> inQueueB2_;
    TQue<TPosition::CO1, 1> outQueueCO1_;
    uint32_t k_;
    uint32_t aDvalue_, bDvalue_;
    uint32_t l1Prefetch_;
    uint32_t baseM_, baseN_, baseK_;
    uint32_t baseMK_, baseKN_, baseMN_;
};

// ============================================================================
// HyenaFftKernel: Two-GEMM kernel (Real + Imag parts)
// ============================================================================
template <typename T>
class HyenaFftKernel {
public:
    __aicore__ inline HyenaFftKernel() {}
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR cosWT, GM_ADDR sinWT,
                                GM_ADDR outRe, GM_ADDR outIm,
                                GM_ADDR tilingGM, TPipe *pipe);
    __aicore__ inline void Process();

private:
    GlobalTensor<T> xGM_;
    GlobalTensor<T> cosWtGM_;
    GlobalTensor<T> sinWtGM_;
    GlobalTensor<float> outReGM_;
    GlobalTensor<float> outImGM_;
    MatmulCompute<T> mmRe_;
    MatmulCompute<T> mmIm_;
    BlockScheduler sched_;
    HyenaFftTiling tiling_;
};

template <typename T>
__aicore__ inline void HyenaFftKernel<T>::Init(
    GM_ADDR x, GM_ADDR cosWT, GM_ADDR sinWT,
    GM_ADDR outRe, GM_ADDR outIm,
    GM_ADDR tilingGM, TPipe *pipe)
{
    CopyTiling(&tiling_, tilingGM);

    xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x),
                         tiling_.M * tiling_.K);
    cosWtGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(cosWT),
                             tiling_.K * tiling_.N);
    sinWtGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(sinWT),
                             tiling_.K * tiling_.N);
    outReGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(outRe),
                             tiling_.M * tiling_.N);
    outImGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(outIm),
                             tiling_.M * tiling_.N);

    int coreIdx = GetBlockIdx() / GetSubBlockNum();
    sched_.Init(tiling_.M, tiling_.N, tiling_.baseM, tiling_.baseN,
                GetBlockNum(), coreIdx);

    if ASCEND_IS_AIC {
        mmRe_.Init(tiling_.K, tiling_.K, tiling_.N,
                   tiling_.baseM, tiling_.baseN, tiling_.baseK,
                   tiling_.l1Prefetch, *pipe);
        mmIm_.Init(tiling_.K, tiling_.K, tiling_.N,
                   tiling_.baseM, tiling_.baseN, tiling_.baseK,
                   tiling_.l1Prefetch, *pipe);
    }
}

template <typename T>
__aicore__ inline void HyenaFftKernel<T>::Process()
{
    int mIdx, nIdx;
    while (sched_.HasNext()) {
        sched_.Next(mIdx, nIdx);
        if ASCEND_IS_AIC {
            auto aBlock = xGM_[mIdx * tiling_.baseM * tiling_.K];
            auto bReBlock = cosWtGM_[nIdx * tiling_.baseN];
            auto bImBlock = sinWtGM_[nIdx * tiling_.baseN];
            auto cReBlock = outReGM_[(mIdx * tiling_.baseM) * tiling_.N +
                                     nIdx * tiling_.baseN];
            auto cImBlock = outImGM_[(mIdx * tiling_.baseM) * tiling_.N +
                                     nIdx * tiling_.baseN];

            mmRe_.ComputeBlock(aBlock, bReBlock, cReBlock);
            mmIm_.ComputeBlock(aBlock, bImBlock, cImBlock);
        }
    }
}

