extern "C" __global__ __aicore__ void hyena_fft_size_padding_rfft_fp32(
    GM_ADDR x, GM_ADDR cosWT, GM_ADDR sinWT,
    GM_ADDR outRe, GM_ADDR outIm, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
    TPipe pipe;
    HyenaFftKernel<float> kernel;
    kernel.Init(x, cosWT, sinWT, outRe, outIm, tiling, &pipe);
    kernel.Process();
}

