// ============================================================================
// HyenaFftKernel: Two-GEMM kernel
// ============================================================================
template <typename T>
class HyenaFftKernel {
public:
    __aicore__ inline HyenaFftKernel() {}
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR cosWT, GM_ADDR sinWT,
                                GM_ADDR outRe, GM_ADDR outIm,
                                GM_ADDR tilingGM, TPipe *pipe);
    __aicore__ inline void Process();

private:
    GlobalTensor<T> xGM_;
    GlobalTensor<T> cosWtGM_;
    GlobalTensor<T> sinWtGM_;
    GlobalTensor<float> outReGM_;
    GlobalTensor<float> outImGM_;
    MatmulCompute<T> mmRe_;
    MatmulCompute<T> mmIm_;
    BlockScheduler sched_;
    HyenaFftTiling tiling_;
};

template <typename T>
__aicore__ inline void HyenaFftKernel<T>::Init(
    GM_ADDR x, GM_ADDR cosWT, GM_ADDR sinWT,
    GM_ADDR outRe, GM_ADDR outIm,
    GM_ADDR tilingGM, TPipe *pipe)
{
    CopyTiling(&tiling_, tilingGM);

    xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x),
                         tiling_.M * tiling_.K);
    cosWtGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(cosWT),
                             tiling_.K * tiling_.N);
    sinWtGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(sinWT),
                             tiling_.K * tiling_.N);
    outReGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(outRe),
                             tiling_.M * tiling_.N);
    outImGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(outIm),
                             tiling_.M * tiling_.N);

    int coreIdx = GetBlockIdx() / GetSubBlockNum();
    sched_.Init(tiling_.M, tiling_.N, tiling_.baseM, tiling_.baseN,
                GetBlockNum(), coreIdx);

    if ASCEND_IS_AIC {
        mmRe_.Init(tiling_.K, tiling_.K, tiling_.N,
                   tiling_.baseM, tiling_.baseN, tiling_.baseK,
                   tiling_.l1Prefetch, *pipe);
        mmIm_.Init(tiling_.K, tiling_.K, tiling_.N,
                   tiling_.baseM, tiling_.baseN, tiling_.baseK,
                   tiling_.l1Prefetch, *pipe);
    }
}

template <typename T>
__aicore__ inline void HyenaFftKernel<T>::Process()
{
    int mIdx, nIdx;
    while (sched_.HasNext()) {
        sched_.Next(mIdx, nIdx);
        if ASCEND_IS_AIC {
            auto aBlock = xGM_[mIdx * tiling_.baseM * tiling_.K];
            auto bReBlock = cosWtGM_[nIdx * tiling_.baseN];
            auto bImBlock = sinWtGM_[nIdx * tiling_.baseN];
            auto cReBlock = outReGM_[(mIdx * tiling_.baseM) * tiling_.N +
                                     nIdx * tiling_.baseN];
            auto cImBlock = outImGM_[(mIdx * tiling_.baseM) * tiling_.N +
                                     nIdx * tiling_.baseN];

            mmRe_.ComputeBlock(aBlock, bReBlock, cReBlock);
            mmIm_.ComputeBlock(aBlock, bImBlock, cImBlock);
        }
    }
}

