 */

#include "kernel_operator.h"

using namespace AscendC;

// ============================================================================
// Inline utilities (preprocess step needs everything in this file or op_kernel/)
// ============================================================================

// CopyTiling: copy tiling struct from GM to local
template<typename T>
__aicore__ inline void _CopyTiling(T *tiling, GM_ADDR tilingGM)
{
    int32_t *ptr = reinterpret_cast<int32_t *>(tiling);
    auto tiling32 = reinterpret_cast<__gm__ int32_t *>(tilingGM);
    for (size_t i = 0; i < sizeof(T) / sizeof(int32_t); ++i, ++ptr) {
        *ptr = *(tiling32 + i);
    }
}

// Tiling parameters (must match op_host)
constexpr int32_t DEFAULT_BASE_M = 64;
constexpr int32_t DEFAULT_BASE_N = 64;
constexpr int32_t DEFAULT_BASE_K = 64;
constexpr int32_t DEFAULT_L1_PREFETCH = 4;

#pragma pack(push, 8)
struct HyenaFftTiling {
    int32_t M;
    int32_t K;
    int32_t N;
    int32_t baseM;
    int32_t baseN;
    int32_t baseK;
    int32_t l1Prefetch;
};
#pragma pack(pop)

// BlockScheduler: distributes (M,N) GEMM blocks across cores
class BlockScheduler {
public:
    __aicore__ inline void Init(int M, int N, int baseM, int baseN,
                                int numBlocks, int blockIdx)
    {
        if (baseM == 0 || baseN == 0 || numBlocks == 0) {
            mBlocks_ = 0; nBlocks_ = 0;
            startBlock_ = 0; endBlock_ = 0; current_ = 0;
            return;
        }
        mBlocks_ = M / baseM;
        nBlocks_ = N / baseN;
        int totalBlocks = mBlocks_ * nBlocks_;
        int blocksPerCore = totalBlocks / numBlocks;
        int remainder = totalBlocks % numBlocks;
        startBlock_ = blockIdx * blocksPerCore +
                       (blockIdx < remainder ? blockIdx : remainder);
        endBlock_ = startBlock_ + blocksPerCore +
                    (blockIdx < remainder ? 1 : 0);
        current_ = startBlock_;
    }
    __aicore__ inline bool HasNext() { return current_ < endBlock_; }
    __aicore__ inline void Next(int &mIdx, int &nIdx) {
        mIdx = current_ / nBlocks_;
        nIdx = current_ % nBlocks_;
        current_++;
    }
private:
    int mBlocks_, nBlocks_, startBlock_, endBlock_, current_;
};

// ============================================================================
// Tile helpers: GM(ND) <-> L1(Nz) / L0A(Zz) / L0B(Zn) / Fixpipe L0C(Nz)->GM(ND)
// ============================================================================

template<typename T>
__aicore__ inline void LoadNdGmToNzL1(const LocalTensor<T> &dst,
                                      const GlobalTensor<T> &src,
                                      uint32_t m, uint32_t n, uint32_t ld)
{
    Nd2NzParams params;
    params.ndNum = 1;
    params.nValue = m;
    params.dValue = n;
    params.srcNdMatrixStride = 0;
    params.srcDValue = ld;
    params.dstNzC0Stride = m;
    params.dstNzNStride = 1;
    params.dstNzMatrixStride = 0;
    DataCopy(dst, src, params);
}

template<typename T>
__aicore__ inline void LoadNzL1ToZzL0A(const LocalTensor<T> &dst,
                                       const LocalTensor<T> &src,
                                       uint32_t m, uint32_t k, uint32_t colC0Stride)
{
    LoadData3DParamsV2<T> params;
    params.l1H = 1;
    params.l1W = colC0Stride;
    params.channelSize = k;
    params.kExtension = k;
    params.mExtension = m;
    params.strideH = 1; params.strideW = 1;
    params.filterH = 1; params.filterW = 1;
    params.dilationFilterH = 1; params.dilationFilterW = 1;
    LoadData(dst, src, params);
}

template<typename T>
__aicore__ inline void LoadNzL1ToZnL0B(const LocalTensor<T> &dst,
                                       const LocalTensor<T> &src,
                                       uint32_t k, uint32_t n, uint32_t colC0Stride)
{
    LoadData3DParamsV2<T> params;
    params.l1H = 1;
    params.l1W = colC0Stride;
    params.channelSize = n;
    params.kExtension = n;
    params.mExtension = k;
    params.strideH = 1; params.strideW = 1;
    params.filterH = 1; params.filterW = 1;
    params.dilationFilterH = 1; params.dilationFilterW = 1;
    LoadData(dst, src, params);
}

template<typename T>
__aicore__ inline void FixpipeNzL0cToNdGm(const GlobalTensor<T> &dst,
                                          const LocalTensor<T> &src,
                                          uint32_t m, uint32_t n)
{
    FixpipeParamsV220 params;
    params.nSize = n;
    params.mSize = m;
    params.srcStride = m;
    params.dstStride = n;
    params.ndNum = 1;
    params.srcNdStride = 0;
    params.dstNdStride = 0;
    Fixpipe(dst, src, params);
}

// ============================================================================
// MatmulCompute: Encapsulates one GEMM (GM->L1->L0->Mmad->L0C->GM)
// ============================================================================
template <typename T>
class MatmulCompute {
    static constexpr uint32_t C0 = 32 / sizeof(T);

public:
    __aicore__ inline MatmulCompute() {}

    __aicore__ inline void Init(uint32_t k, uint32_t lda, uint32_t ldb,
                                uint32_t baseM, uint32_t baseN, uint32_t baseK,
                                uint32_t l1Prefetch, TPipe &pipe)
    {
        baseM_ = baseM; baseN_ = baseN; baseK_ = baseK;
        l1Prefetch_ = l1Prefetch;
        baseMK_ = baseM_ * baseK_;
        baseKN_ = baseK_ * baseN_;
        baseMN_ = baseM_ * baseN_;
        k_ = k; aDvalue_ = lda; bDvalue_ = ldb;

        pipe.InitBuffer(inQueueA1_, 2, baseMK_ * l1Prefetch_ * sizeof(T));
        pipe.InitBuffer(inQueueA2_, 2, baseMK_ * sizeof(T));
        pipe.InitBuffer(inQueueB1_, 2, baseKN_ * l1Prefetch_ * sizeof(T));
        pipe.InitBuffer(inQueueB2_, 2, baseKN_ * sizeof(T));
        pipe.InitBuffer(outQueueCO1_, 1, baseMN_ * sizeof(float));
    }

    __aicore__ inline void ComputeBlock(
        const GlobalTensor<T> &aBlock, const GlobalTensor<T> &bBlock,
        GlobalTensor<float> &cBlock)
    {
        LocalTensor<float> c1Local = outQueueCO1_.AllocTensor<float>();
        uint32_t kTiles = k_ / baseK_;

        for (uint32_t outer = 0; outer < kTiles; outer += l1Prefetch_) {
            uint32_t count = (kTiles - outer < l1Prefetch_)
                                 ? (kTiles - outer) : l1Prefetch_;
            uint32_t kLen = count * baseK_;

            // CopyA: GM -> L1
            {
                auto a1Local = inQueueA1_.AllocTensor<T>();
                LoadNdGmToNzL1(a1Local,
                               aBlock[outer * baseK_], baseM_, kLen, aDvalue_);
                inQueueA1_.EnQue(a1Local);
            }

            // CopyB: GM -> L1
            {
                auto b1Local = inQueueB1_.AllocTensor<T>();
                LoadNdGmToNzL1(b1Local,
                               bBlock[outer * baseK_ * bDvalue_],
                               baseK_ * count, baseN_, bDvalue_);
                inQueueB1_.EnQue(b1Local);
            }

            LocalTensor<T> a1Local = inQueueA1_.DeQue<T>();
            LocalTensor<T> b1Local = inQueueB1_.DeQue<T>();

            for (uint32_t i = 0; i < count; i++) {
                // SplitA: L1 -> L0A
                {
                    auto a2Local = inQueueA2_.AllocTensor<T>();
                    LoadNzL1ToZzL0A(a2Local, a1Local[i * baseMK_],
                                    baseM_, baseK_, baseM_);
                    inQueueA2_.EnQue(a2Local);
                }
                // SplitB: L1 -> L0B
                {
                    auto b2Local = inQueueB2_.AllocTensor<T>();
                    LoadNzL1ToZnL0B(b2Local, b1Local[i * baseKN_],
                                    baseK_, baseN_, C0 * baseK_);
                    inQueueB2_.EnQue(b2Local);
                }
                // Compute: Mmad
                {
                    LocalTensor<T> a2Local = inQueueA2_.DeQue<T>();
                    LocalTensor<T> b2Local = inQueueB2_.DeQue<T>();
                    MmadParams mmadParams;
                    mmadParams.m = baseM_;
                    mmadParams.n = baseN_;
                    mmadParams.k = baseK_;
                    mmadParams.cmatrixInitVal = (outer + i == 0);
                    Mmad(c1Local, a2Local, b2Local, mmadParams);
                    inQueueA2_.FreeTensor(a2Local);
                    inQueueB2_.FreeTensor(b2Local);
                }
            }

            inQueueA1_.FreeTensor(a1Local);
            inQueueB1_.FreeTensor(b1Local);
        }

        // CopyOut: L0C -> GM
        outQueueCO1_.EnQue(c1Local);
        {
