        int blocksPerCore = totalBlocks / numBlocks;
        int remainder = totalBlocks % numBlocks;
        startBlock_ = blockIdx * blocksPerCore +
                       (blockIdx < remainder ? blockIdx : remainder);
        endBlock_ = startBlock_ + blocksPerCore +
                    (blockIdx < remainder ? 1 : 0);
        current_ = startBlock_;
    }
