// ---- Combined GEMM for both real and imag ----
template <typename T>
class CombinedGemm {
    static constexpr uint32_t C0 = 32 / sizeof(T);
public:
    __aicore__ inline CombinedGemm() {}

    __aicore__ inline void Init(
        uint32_t k, uint32_t lda, uint32_t ldb,
        uint32_t baseM, uint32_t baseN, uint32_t baseK,
        uint32_t l1Prefetch, TPipe &pipe)
    {
        baseM_ = baseM; baseN_ = baseN; baseK_ = baseK;
        l1Prefetch_ = l1Prefetch;
        baseMK_ = baseM_ * baseK_; baseKN_ = baseK_ * baseN_;
        baseMN_ = baseM_ * baseN_;
        k_ = k; aDvalue_ = lda; bDvalue_ = ldb;

        pipe.InitBuffer(inQueueA1_, 2, baseMK_ * l1Prefetch_ * sizeof(T));
        pipe.InitBuffer(inQueueA2_, 2, baseMK_ * sizeof(T));
        pipe.InitBuffer(inQueueB1_, 2, baseKN_ * l1Prefetch_ * sizeof(T));
        pipe.InitBuffer(inQueueB2_, 2, baseKN_ * sizeof(T));
        pipe.InitBuffer(outQueueCO1_, 1, baseMN_ * sizeof(float));
    }

    __aicore__ inline void SetOutput(GlobalTensor<float> &cBlock) {
        cBlock_ = &cBlock;
    }

    __aicore__ inline void ComputeBlock(
        const GlobalTensor<T> &aBlock, 
        const GlobalTensor<T> &bBlock)
    {
        // Allocate L0C at the beginning (persistent across K-loop)
        LocalTensor<float> cLocal = outQueueCO1_.AllocTensor<float>();
        uint32_t kTiles = k_ / baseK_;

        for (uint32_t outer = 0; outer < kTiles; outer += l1Prefetch_) {
            uint32_t count = (kTiles - outer < l1Prefetch_)
                                 ? (kTiles - outer) : l1Prefetch_;
            uint32_t kLen = count * baseK_;

            // CopyA: GM -> L1
            {
                auto a1Local = inQueueA1_.AllocTensor<T>();
                LoadNdGmToNzL1(a1Local, aBlock[outer * baseK_],
                               baseM_, kLen, aDvalue_);
                inQueueA1_.EnQue(a1Local);
            }
            // CopyB: GM -> L1
            {
                auto b1Local = inQueueB1_.AllocTensor<T>();
                LoadNdGmToNzL1(b1Local, bBlock[outer * baseK_ * bDvalue_],
                               baseK_ * count, baseN_, bDvalue_);
                inQueueB1_.EnQue(b1Local);
            }

            LocalTensor<T> a1Local = inQueueA1_.DeQue<T>();
            LocalTensor<T> b1Local = inQueueB1_.DeQue<T>();

            for (uint32_t i = 0; i < count; i++) {
                {
                    auto a2Local = inQueueA2_.AllocTensor<T>();
                    LoadNzL1ToZzL0A(a2Local, a1Local[i * baseMK_],
                                    baseM_, baseK_, baseM_);
                    inQueueA2_.EnQue(a2Local);
                }
                {
                    auto b2Local = inQueueB2_.AllocTensor<T>();
                    LoadNzL1ToZnL0B(b2Local, b1Local[i * baseKN_],
                                    baseK_, baseN_, C0 * baseK_);
                    inQueueB2_.EnQue(b2Local);
                }
                {
                    LocalTensor<T> a2Local = inQueueA2_.DeQue<T>();
                    LocalTensor<T> b2Local = inQueueB2_.DeQue<T>();
                    MmadParams mmadParams;
                    mmadParams.m = baseM_;
                    mmadParams.n = baseN_;
                    mmadParams.k = baseK_;
                    mmadParams.cmatrixInitVal = (outer + i == 0);
                    Mmad(cLocal, a2Local, b2Local, mmadParams);
                    inQueueA2_.FreeTensor(a2Local);
                    inQueueB2_.FreeTensor(b2Local);
                }
            }
            inQueueA1_.FreeTensor(a1Local);
            inQueueB1_.FreeTensor(b1Local);
        }

        // CopyOut: L0C -> GM
        outQueueCO1_.EnQue(cLocal);
        {
            auto cOut = outQueueCO1_.DeQue<float>();
            FixpipeNzL0cToNdGm(*cBlock_, cOut, baseM_, baseN_);
            outQueueCO1_.FreeTensor(cOut);
        }
    }

private:
    TQue<TPosition::A1, 1> inQueueA1_;
    TQue<TPosition::A2, 1> inQueueA2_;
    TQue<TPosition::B1, 1> inQueueB1_;
    TQue<TPosition::B2, 1> inQueueB2_;
    TQue<TPosition::CO1, 1> outQueueCO1_;
    uint32_t k_, aDvalue_, bDvalue_, l1Prefetch_;
    uint32_t baseM_, baseN_, baseK_, baseMK_, baseKN_, baseMN_;
    GlobalTensor<float> *cBlock_{nullptr};
};

