template <typename T>
__aicore__ inline void HyenaFftKernel<T>::Init(
    GM_ADDR x, GM_ADDR cosWT, GM_ADDR sinWT,
    GM_ADDR outRe, GM_ADDR outIm,
    GM_ADDR tilingGM, TPipe *pipe)
{
    _CopyTiling(&tiling_, tilingGM);
    xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), tiling_.M * tiling_.K);
    cosWtGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(cosWT), tiling_.K * tiling_.N);
    sinWtGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(sinWT), tiling_.K * tiling_.N);
    outReGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(outRe), tiling_.M * tiling_.N);
    outImGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(outIm), tiling_.M * tiling_.N);

    int coreIdx = GetBlockIdx() / GetSubBlockNum();
    sched_.Init(tiling_.M, tiling_.N, tiling_.baseM, tiling_.baseN,
                GetBlockNum(), coreIdx);

    if ASCEND_IS_AIC {
        gemmRe_.Init(tiling_.K, tiling_.K, tiling_.N,
                     tiling_.baseM, tiling_.baseN, tiling_.baseK,
                     tiling_.l1Prefetch, *pipe);
        gemmIm_.Init(tiling_.K, tiling_.K, tiling_.N,
                     tiling_.baseM, tiling_.baseN, tiling_.baseK,
                     tiling_.l1Prefetch, *pipe);
    }
}

template <typename T>
__aicore__ inline void HyenaFftKernel<T>::Process()
{
    int mIdx, nIdx;
    while (sched_.HasNext()) {
        sched_.Next(mIdx, nIdx);
        if ASCEND_IS_AIC {
            auto aBlock = xGM_[mIdx * tiling_.baseM * tiling_.K];
            auto bReBlock = cosWtGM_[nIdx * tiling_.baseN];
            auto bImBlock = sinWtGM_[nIdx * tiling_.baseN];
            auto cReBlock = outReGM_[(mIdx * tiling_.baseM) * tiling_.N +
                                     nIdx * tiling_.baseN];
            auto cImBlock = outImGM_[(mIdx * tiling_.baseM) * tiling_.N +
                                     nIdx * tiling_.baseN];

            gemmRe_.SetOutput(cReBlock);
            gemmRe_.ComputeBlock(aBlock, bReBlock);
            PipeBarrier<PIPE_ALL>();

            gemmIm_.SetOutput(cImBlock);
            gemmIm_.ComputeBlock(aBlock, bImBlock);
            PipeBarrier<PIPE_ALL>();
        }
    }
}

