        baseM_ = tiling_.baseM; baseN_ = tiling_.baseN;
        baseK_ = tiling_.baseK; l1p_ = tiling_.l1Prefetch;
        baseMK_ = baseM_ * baseK_; baseKN_ = baseK_ * baseN_;
        baseMN_ = baseM_ * baseN_;
        k_ = tiling_.K; aDval_ = tiling_.K; bDval_ = tiling_.N;

        if ASCEND_IS_AIC {
            pipe->InitBuffer(inQueueA1_, 2, baseMK_ * l1p_ * sizeof(T));
            pipe->InitBuffer(inQueueA2_, 2, baseMK_ * sizeof(T));
            pipe->InitBuffer(inQueueB1_, 2, baseKN_ * l1p_ * sizeof(T));
            pipe->InitBuffer(inQueueB2_, 2, baseKN_ * sizeof(T));
            pipe->InitBuffer(outQueueCO1_, 1, baseMN_ * sizeof(float));
        }
    }
    __aicore__ inline void Process() {
        int mIdx, nIdx;
        while (sched_.HasNext()) {
            sched_.Next(mIdx, nIdx);
            if ASCEND_IS_AIC {
                auto aBlock = xGM_[mIdx * baseM_ * k_];
                auto bBlock = cosWtGM_[nIdx * baseN_];
                auto cBlock = outReGM_[(mIdx * baseM_) * tiling_.N + nIdx * baseN_];
                ComputeOneGemm(aBlock, bBlock, cBlock);
            }
        }
    }

private:
    __aicore__ inline void ComputeOneGemm(
        const GlobalTensor<T> &aBlock, const GlobalTensor<T> &bBlock,
        GlobalTensor<float> &cBlock)
    {
        LocalTensor<float> cLocal = outQueueCO1_.AllocTensor<float>();
        uint32_t kTiles = k_ / baseK_;

        for (uint32_t outer = 0; outer < kTiles; outer += l1p_) {
            uint32_t cnt = (kTiles - outer < l1p_) ? (kTiles - outer) : l1p_;
            uint32_t kLen = cnt * baseK_;

            // CopyA: GM->L1
            {
                auto a1 = inQueueA1_.AllocTensor<T>();
                _LoadNdA(a1, aBlock[outer * baseK_], baseM_, kLen, aDval_);
                inQueueA1_.EnQue(a1);
            }
            // CopyB: GM->L1
            {
                auto b1 = inQueueB1_.AllocTensor<T>();
                _LoadNdBL1(b1, bBlock[outer * baseK_ * bDval_],
                           baseK_ * cnt, baseN_, bDval_);
                inQueueB1_.EnQue(b1);
            }

            LocalTensor<T> a1L = inQueueA1_.DeQue<T>();
            LocalTensor<T> b1L = inQueueB1_.DeQue<T>();

            for (uint32_t i = 0; i < cnt; i++) {
                {
                    auto a2 = inQueueA2_.AllocTensor<T>();
                    _SplitL0A(a2, a1L[i * baseMK_], baseM_, baseK_, baseM_);
                    inQueueA2_.EnQue(a2);
                }
                {
                    auto b2 = inQueueB2_.AllocTensor<T>();
                    _SplitL0B(b2, b1L[i * baseKN_], baseK_, baseN_, C0 * baseK_);
                    inQueueB2_.EnQue(b2);
                }
                {
                    auto a2 = inQueueA2_.DeQue<T>();
                    auto b2 = inQueueB2_.DeQue<T>();
                    MmadParams mp;
                    mp.m = baseM_; mp.n = baseN_; mp.k = baseK_;
                    mp.cmatrixInitVal = (outer + i == 0);
                    Mmad(cLocal, a2, b2, mp);
                    inQueueA2_.FreeTensor(a2);
                    inQueueB2_.FreeTensor(b2);
                }
            }
            inQueueA1_.FreeTensor(a1L);
            inQueueB1_.FreeTensor(b1L);
        }

        outQueueCO1_.EnQue(cLocal);
        {
            auto co = outQueueCO1_.DeQue<float>();
            _Fixpipe(cBlock, co, baseM_, baseN_);
            outQueueCO1_.FreeTensor(co);
        }
    }

    GlobalTensor<T> xGM_, cosWtGM_, sinWtGM_;
    GlobalTensor<float> outReGM_, outImGM_;
    HyenaFftTiling tiling_;
    BlockScheduler sched_;
    uint32_t baseM_, baseN_, baseK_, baseMK_, baseKN_, baseMN_;
    uint32_t k_, aDval_, bDval_, l1p_;
    TQue<TPosition::A1, 1> inQueueA1_;
    TQue<TPosition::A2, 1> inQueueA2_;
    TQue<TPosition::B1, 1> inQueueB1_;
    TQue<TPosition::B2, 1> inQueueB2_;
    TQue<TPosition::CO1, 1> outQueueCO1_;
};

