16	std::tuple<at::Tensor, at::Tensor> hyena_fft_size_padding_rfft(
17	    const at::Tensor &x,
18	    const at::Tensor &cosWT,
19	    const at::Tensor &sinWT)
20	{
21	    auto dtype = x.scalar_type();
22	    TORCH_CHECK(x.dim() == 2, "x must be 2D [M, K]");
23	    TORCH_CHECK(cosWT.dim() == 2, "cosWT must be 2D [K, N]");
24	    TORCH_CHECK(sinWT.dim() == 2, "sinWT must be 2D [K, N]");
25	    TORCH_CHECK(x.sizes()[1] == cosWT.sizes()[0], "K dimension mismatch");
26	    TORCH_CHECK(cosWT.sizes()[1] == sinWT.sizes()[1], "N dimension mismatch");
27	
28	    int64_t M = x.sizes()[0];
29	    int64_t K = x.sizes()[1];
30	    int64_t N = cosWT.sizes()[1];
31	
32	    // Validate padded dimensions
33	    TORCH_CHECK(M % DEFAULT_BASE_M == 0, "M must be padded to multiple of baseM");
34	    TORCH_CHECK(K % DEFAULT_BASE_K == 0, "K must be padded to multiple of baseK");
35	    TORCH_CHECK(N % DEFAULT_BASE_N == 0, "N must be padded to multiple of baseN");
36	
37	    // Core count
38	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
39	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
40	    int64_t usedCoreNum = (coreNum > 20) ? 20 : coreNum;
41	
42	    // Block scheduling
43	    int64_t mBlocks = M / DEFAULT_BASE_M;
44	    int64_t nBlocks = N / DEFAULT_BASE_N;
45	    int64_t totalBlocks = mBlocks * nBlocks;
46	    int64_t blockDim = static_cast<int64_t>(usedCoreNum);
47	    if (totalBlocks < blockDim) {
48	        blockDim = totalBlocks;
49	    }
50	    if (blockDim < 1) blockDim = 1;
51	
52	    // Allocate output tensors
53	    at::Tensor outRe = at::empty({M, N},
54	                                  at::device(at::kPrivateUse1).dtype(at::kFloat));
55	    at::Tensor outIm = at::empty({M, N},
56	                                  at::device(at::kPrivateUse1).dtype(at::kFloat));
57	
58	    // Build tiling data
