155	    __aicore__ inline void ComputeOneGemm(
156	        const GlobalTensor<T> &aBlock, const GlobalTensor<T> &bBlock,
157	        GlobalTensor<float> &cBlock)
158	    {
159	        LocalTensor<float> cLocal = outQueueCO1_.AllocTensor<float>();
160	        uint32_t kTiles = k_ / baseK_;
161	
162	        for (uint32_t outer = 0; outer < kTiles; outer += l1p_) {
163	            uint32_t cnt = (kTiles - outer < l1p_) ? (kTiles - outer) : l1p_;
164	            uint32_t kLen = cnt * baseK_;
165	
166	            // CopyA: GM->L1
167	            {
168	                auto a1 = inQueueA1_.AllocTensor<T>();
169	                _LoadNdA(a1, aBlock[outer * baseK_], baseM_, kLen, aDval_);
170	                inQueueA1_.EnQue(a1);
171	            }
172	            // CopyB: GM->L1
173	            {
174	                auto b1 = inQueueB1_.AllocTensor<T>();
175	                _LoadNdBL1(b1, bBlock[outer * baseK_ * bDval_],
176	                           baseK_ * cnt, baseN_, bDval_);
177	                inQueueB1_.EnQue(b1);
178	            }
179	
180	            LocalTensor<T> a1L = inQueueA1_.DeQue<T>();
181	            LocalTensor<T> b1L = inQueueB1_.DeQue<T>();
182	
183	            for (uint32_t i = 0; i < cnt; i++) {
184	                {
185	                    auto a2 = inQueueA2_.AllocTensor<T>();
186	                    _SplitL0A(a2, a1L[i * baseMK_], baseM_, baseK_, baseM_);
187	                    inQueueA2_.EnQue(a2);
188	                }
189	                {
190	                    auto b2 = inQueueB2_.AllocTensor<T>();
191	                    _SplitL0B(b2, b1L[i * baseK_ * C0], baseK_, baseN_, kLen);
192	                    inQueueB2_.EnQue(b2);
193	                }
194	                {
195	                    auto a2 = inQueueA2_.DeQue<T>();
196	                    auto b2 = inQueueB2_.DeQue<T>();
197	                    MmadParams mp;
198	                    mp.m = baseM_; mp.n = baseN_; mp.k = baseK_;
199	                    mp.cmatrixInitVal = (outer + i == 0);
200	                    Mmad(cLocal, a2, b2, mp);
201	                    inQueueA2_.FreeTensor(a2);
202	                    inQueueB2_.FreeTensor(b2);
203	                }
204	            }
205	            inQueueA1_.FreeTensor(a1L);
206	            inQueueB1_.FreeTensor(b1L);
207	        }
208	
209	        outQueueCO1_.EnQue(cLocal);
210	        {
211	            auto co = outQueueCO1_.DeQue<float>();
212	            _Fixpipe(cBlock, co, baseM_, baseN_);
213	            outQueueCO1_.FreeTensor(co);
214	        }
215	    }
